from lib import *
import icons
icons.P['ban']=['<circle cx="12" cy="12" r="10"/>','m4.9 4.9 14.2 14.2']
HD=lambda n,s='bot kelas': f'<div style="margin:0 -12px;background:#0B6B5B;color:#fff;padding:9px 14px;display:flex;gap:10px;align-items:center;font-size:12px;font-weight:600"><span>[[back]]</span><div style="width:30px;height:30px;border-radius:50%;background:#FFC928;color:#1C1B1F;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:800">IX</div><div>{n}<div style="font-size:9px;font-weight:400">{s}</div></div></div>'
def chat(inner): return HD('IX-H Hub')+f'<div style="margin:0 -12px;background:#EADFC8;height:624px;padding:12px">{inner}</div>'
def L(t,tm): return f'<div style="background:#fff;border-radius:3px 12px 12px 12px;padding:8px 10px;font-size:10.5px;line-height:1.5;max-width:86%;margin-bottom:8px;box-shadow:0 1px 0 rgba(0,0,0,.1)"><b>IX-H Hub</b><br>{t}<div class="t3" style="text-align:right">{tm}</div></div>'
def Rr(t,tm): return f'<div style="background:#D9FDD3;border-radius:12px 3px 12px 12px;padding:8px 10px;font-size:10.5px;line-height:1.5;max-width:70%;margin:0 0 8px auto;box-shadow:0 1px 0 rgba(0,0,0,.1)">{t}<div class="t3" style="text-align:right">{tm} ✓✓</div></div>'
def day(t): return f'<div style="text-align:center;margin:2px 0 10px"><span style="background:#fff;border-radius:8px;padding:2px 10px;font-size:9.5px;color:#6B6458">{t}</span></div>'
def cap(t): return f'<div class="t3" style="text-align:center;margin-top:10px">{t}</div>'
tagih='Halo Rangga, ini tagihan kas IX-H: <b>Kas Minggu ke-1 November</b>, Rp6.000. Balas <b>STOP</b> untuk berhenti.'
s1=phone('1. Siswa / Ortu Balas STOP',chat(day('Selasa, 3 Nov')+L(tagih,'15.30')+Rr('STOP','15.52')+L('Baik. Kamu tidak akan menerima pesan dari IX-H Hub lagi. Balas <b>MULAI</b> kapan saja untuk aktif kembali.','15.52')+cap('Percakapan di WhatsApp siswa / orang tua')))
def nt(ic,t,d,tm,u=False,chip=''): return f'<div class="card"><div class="row"><div class="ic" style="{"background:#FFC928;border:2px solid #1C1B1F" if u else ""}">[[{ic}]]</div><div style="flex:1"><div class="t1">{t}</div><div class="t3">{d}</div><div class="t3">{tm}</div></div>{chip}</div></div>'
s2=phone('2. Notifikasi ke Admin & Pengurus',bar('Notifikasi')+'<div class="t3" style="font-weight:700;margin:2px 2px 6px">HARI INI</div>'
+nt('check','Rangga Putra aktif kembali','Membalas MULAI • pesan bot aktif lagi','Rabu 07.12',True,'<span class="chip cg">Valid</span>')
+'<div class="t3" style="font-weight:700;margin:8px 2px 6px">KEMARIN</div>'
+nt('ban','Rangga Putra berhenti menerima pesan','Membalas STOP • bot tidak mengirim pesan lagi','Selasa 15.52',False,'<span class="chip cy">Berhenti</span>')
+nt('send','Tagihan terkirim ke 29 siswa','Kas Minggu ke-1 Nov • 26 terkirim, 3 gagal','Selasa 15.30')
+'<div class="al ab" style="margin-top:8px"><span>[[info]]</span><span>Notifikasi STOP/MULAI hanya untuk <b>Admin dan Pengurus</b>. Ketuk untuk membuka status pengiriman; Admin juga bisa ke Detail Pengguna.</span></div>')
s3=phone('3. Status Nomor: Berhenti',bar('Detail Pengguna')+'''<div style="text-align:center;margin-top:2px"><div class="ic" style="width:60px;height:60px;margin:0 auto;background:#FFC928;border:2px solid #1C1B1F;font-weight:800;font-size:19px">RP</div><div style="font-weight:700;font-size:15px;margin-top:5px">Rangga Putra</div><div class="t2">@rangga.p • <span class="chip cb">Siswa</span> <span class="chip cg">Aktif</span></div></div>
<div class="card" style="margin-top:10px"><div class="row sp"><div class="row"><div class="ic">[[phone]]</div><div><div class="t3">WhatsApp</div><div class="t1" style="font-size:13px">0815-2233-4455</div></div></div><span class="chip cy">Berhenti</span></div></div>
<div class="al ay"><span>[[alert]]</span><span>Berhenti sejak <b>Sel, 3 Nov 15.52</b> lewat balasan STOP. Bot tidak mengirim pesan apa pun sampai siswa atau orang tua membalas <b>MULAI</b>.</span></div>
<div class="btn sec">[[copy]] Salin Pesan Tagihan (kirim manual)</div>
<div class="btn" style="background:#EFE8D6;border:1.2px solid #EADFC8;color:#6B6458">[[lock]] Aktifkan Kembali</div><div class="t3" style="text-align:center;margin-top:5px">Admin dan Pengurus tidak bisa mengaktifkan; hanya yang bersangkutan.</div>''')
def rw(ini,n,d,chip,cc): return f'<div class="card" style="padding:8px 10px"><div class="row sp"><div class="row"><div class="ic" style="width:30px;height:30px;font-size:10px;font-weight:700;background:#FFC928;border:1.5px solid #1C1B1F">{ini}</div><div><div class="t1">{n}</div><div class="t3">{d}</div></div></div><span class="chip {cc}">{chip}</span></div></div>'
s4=phone('4. Dilewati saat Kirim Tagihan',bar('Kirim Tagihan')+'''<div class="t3" style="margin:0 2px 6px">Kas Minggu ke-2 November • saat Rangga masih Berhenti</div>
<div class="row" style="gap:6px;margin-bottom:8px"><div class="card" style="flex:1;text-align:center;margin:0"><div style="font-size:19px;font-weight:800;color:#2E9B5A">28</div><div class="t3">Dikirim</div></div><div class="card" style="flex:1;text-align:center;margin:0"><div style="font-size:19px;font-weight:800;color:#B88A00">1</div><div class="t3">Berhenti</div></div><div class="card" style="flex:1;text-align:center;margin:0"><div style="font-size:19px;font-weight:800;color:#D94452">3</div><div class="t3">Bermasalah</div></div></div>
<div class="lbl">Dilewati (4)</div>'''
+rw('RP','Rangga Putra','Berhenti (STOP) • 3 Nov','Berhenti','cy')+rw('EW','Eka Wijaya','Nomor belum diisi','Kosong','cr')+rw('GN','Gita Nuraini','Tidak terdaftar di WA','Tidak di WA','cr')+rw('HS','Hana Safitri','Belum dites','Belum dicek','cx')
+'<div class="al ay"><span>[[info]]</span><span>Siswa yang Berhenti tidak dikirimi pesan, tetapi <b>tagihannya tetap tercatat</b>.</span></div><div class="btn pri">[[send]] Kirim ke 28 Siswa</div><div class="btn sec">[[copy]] Salin Pesan untuk yang Dilewati</div>')
s5=phone('5. Siswa / Ortu Balas MULAI',chat(day('Rabu, 4 Nov')+Rr('MULAI','07.12')+L('Selamat datang kembali! Kamu akan menerima tagihan dan pengingat IX-H Hub lagi. Balas <b>STOP</b> kapan saja untuk berhenti.','07.12')+cap('Kata kunci tidak peka huruf besar/kecil: MULAI atau AKTIF')))
s6=phone('6. Aktifkan lewat Aplikasi',bar('Pesan WhatsApp')+'''<div class="card"><div class="row sp"><div class="row"><div class="ic">[[phone]]</div><div><div class="t3">Nomor kamu</div><div class="t1" style="font-size:13px">0815-••••-4455</div></div></div><span class="chip cy">Berhenti</span></div></div>
<div class="card"><div class="row sp"><div style="flex:1"><div class="t1">Terima pesan kelas</div><div class="t3">Tagihan dan pengingat milikmu dari bot IX-H Hub</div></div><div class="tog off"></div></div></div>
<div class="al ab"><span>[[info]]</span><span>Kamu masih bisa melihat tagihan di aplikasi. Bisa juga aktif lagi dengan membalas <b>MULAI</b> di WhatsApp.</span></div>''',over='''<div class="dim"></div><div class="dlg"><div class="ic" style="width:46px;height:46px;margin:0 auto 8px;background:#FFC928;border:2px solid #1C1B1F">[[bot]]</div><div style="font-weight:700;font-size:14px">Aktifkan pesan WhatsApp?</div><div class="t2" style="margin:4px 0 10px">Bot IX-H Hub akan mengirim tagihan dan pengingat milikmu lagi ke 0815-••••-4455.</div><div class="row" style="gap:8px"><div class="btn sec" style="flex:1;margin:0">Batal</div><div class="btn pri" style="flex:1;margin:0">Aktifkan</div></div></div>''')
def tlr(c,t,d): return f'<div class="row" style="align-items:flex-start;gap:10px;margin-bottom:10px"><div style="width:12px;height:12px;border-radius:50%;background:{c};border:2px solid #1C1B1F;margin-top:3px;flex:none"></div><div><div class="t1">{t}</div><div class="t3">{d}</div></div></div>'
s7=phone('7. Valid Lagi + Riwayat Status',bar('Detail Pengguna')+'''<div style="text-align:center;margin-top:2px"><div class="ic" style="width:60px;height:60px;margin:0 auto;background:#FFC928;border:2px solid #1C1B1F;font-weight:800;font-size:19px">RP</div><div style="font-weight:700;font-size:15px;margin-top:5px">Rangga Putra</div></div>
<div class="card" style="margin-top:10px"><div class="row sp"><div class="row"><div class="ic">[[phone]]</div><div><div class="t3">WhatsApp</div><div class="t1" style="font-size:13px">0815-2233-4455</div></div></div><span class="chip cg">Valid</span></div></div>
<div class="al ag"><span>[[check]]</span><span>Pesan WhatsApp aktif kembali. Tagihan berikutnya dikirim seperti biasa.</span></div>
<div class="lbl" style="margin-top:8px">Riwayat status nomor</div><div class="card" style="padding:10px 12px;margin-top:2px">'''
+tlr('#2E9B5A','Valid','Dites Admin • Jum, 30 Okt 10.05')+tlr('#D9A400','Berhenti','Balas STOP via WhatsApp • Sel, 3 Nov 15.52')+tlr('#2E9B5A','Valid','Balas MULAI via WhatsApp • Rab, 4 Nov 07.12')
+'</div><div class="t3" style="text-align:center;margin-top:6px">Perubahan status juga tercatat di Log Aktivitas.</div>')
R_=rules(span=1,items=['Kata kunci tidak peka huruf: <b>STOP</b> atau <b>BERHENTI</b> untuk berhenti; <b>MULAI</b> atau <b>AKTIF</b> untuk aktif lagi.','Setelah STOP, bot membalas <b>satu konfirmasi</b>, lalu tidak mengirim pesan apa pun lagi, termasuk pengingat.','<b>Admin dan Pengurus tidak bisa mengaktifkan</b>; hanya siswa atau orang tua (balas MULAI atau lewat Profil).','Berhenti hanya menghentikan pesan WhatsApp; <b>tagihan tetap tercatat</b> dan terlihat di aplikasi (Tagihanku).','Pengurus bisa <b>salin pesan</b> dan mengirim manual untuk siswa yang Berhenti.','Setiap STOP/MULAI memicu <b>notifikasi</b> ke Admin dan Pengurus serta masuk <b>Log Aktivitas</b>.','Detail Pengguna <b>khusus Admin</b>; Pengurus melihat status Berhenti di Kirim Tagihan dan Status Pengiriman.','Angka saat Rangga Berhenti: 32 siswa = <b>28 dikirim + 1 berhenti + 3 nomor bermasalah</b>; setelah MULAI kembali 29 + 3.'])
html=page('Alur STOP & MULAI','Siswa/orang tua mengatur sendiri penerimaan pesan bot • bot membalas satu konfirmasi • status nomor tercatat otomatis',[s1,s2,s3,s4,s5,s6,s7,R_])
render(html,'/home/claude/w23/23_alur_stop_mulai.jpg','23_alur_stop_mulai')
